// Harness Search Utility
'use strict';

const fs = require('fs');
const path = require('path');

function searchHarness(repoRoot, query) {
  const results = [];
  const searchDir = path.join(repoRoot, 'src');

  function walkDir(dir) {
    const files = fs.readdirSync(dir);

    for (const file of files) {
      const fullPath = path.join(dir, file);
      const stat = fs.statSync(fullPath);

      if (stat.isDirectory()) {
        walkDir(fullPath);
      } else if (file.endsWith('.js') || file.endsWith('.ts')) {
        const content = fs.readFileSync(fullPath, 'utf-8');
        if (content.includes(query)) {
          results.push(fullPath);
        }
      }
    }
  }

  walkDir(searchDir);
  return results;
}

module.exports = { searchHarness };
```

This file provides a search utility for finding files containing a specific query within the repository.

