// Pipeline Status Tracker
'use strict';

const fs = require('fs');
const path = require('path');

let pipelineState = {
  totalTasks: 0,
  pendingTasks: 0,
  completedTasks: 0,
  failedTasks: 0
};

function updatePipelineStats(repoRoot) {
  const queueDir = path.join(repoRoot, 'queue');

  if (fs.existsSync(queueDir)) {
    const states = ['pending', 'review', 'approved', 'blocked', 'done'];

    for (const state of states) {
      const stateDir = path.join(queueDir, state);
      if (fs.existsSync(stateDir)) {
        const files = fs.readdirSync(stateDir);
        const count = files.length;

        if (state === 'pending') {
          pipelineState.pendingTasks = count;
        } else if (state === 'done') {
          pipelineState.completedTasks = count;
        } else if (state === 'blocked') {
          pipelineState.failedTasks = count;
        }
      }
    }
  }

  pipelineState.totalTasks = pipelineState.pendingTasks + pipelineState.completedTasks + pipelineState.failedTasks;
}

function getPipelineStatus() {
  return { ...pipelineState };
}

module.exports = {
  updatePipelineStats,
  getPipelineStatus
};
```

This file tracks pipeline statistics by counting tasks in different queue states.

