// Task Classifier
'use strict';

function classifyTask(task) {
  const classification = {
    category: 'unknown',
    priority: 'normal',
    estimatedComplexity: 'medium'
  };

  const title = (task.title || '').toLowerCase();
  const description = (task.description || '').toLowerCase();
  const combined = title + ' ' + description;

  // Classify by category
  if (combined.includes('fix') || combined.includes('bug')) {
    classification.category = 'bugfix';
    classification.priority = 'high';
  } else if (combined.includes('feature') || combined.includes('new')) {
    classification.category = 'feature';
    classification.estimatedComplexity = 'high';
  } else if (combined.includes('doc') || combined.includes('documentation')) {
    classification.category = 'documentation';
    classification.estimatedComplexity = 'low';
  } else if (combined.includes('test') || combined.includes('testing')) {
    classification.category = 'testing';
    classification.estimatedComplexity = 'medium';
  }

  // Classify by priority keywords
  if (combined.includes('urgent') || combined.includes('critical') || combined.includes('blocker')) {
    classification.priority = 'critical';
  } else if (combined.includes('low priority') || combined.includes('nice to have')) {
    classification.priority = 'low';
  }

  return classification;
}

module.exports = { classifyTask };
```

This file classifies tasks based on their title and description content, determining category, priority, and estimated complexity.

