// Budget Tracker
'use strict';

const fs = require('fs');
const path = require('path');

class BudgetTracker {
  constructor(configPath) {
    this.configPath = configPath;
    this.budget = this.loadBudget();
  }

  loadBudget() {
    try {
      if (fs.existsSync(this.configPath)) {
        const data = fs.readFileSync(this.configPath, 'utf-8');
        return JSON.parse(data);
      }
    } catch (error) {
      console.error('Failed to load budget config:', error);
    }

    return {
      dailyLimit: 100,
      monthlyLimit: 2500,
      currentDaySpent: 0,
      currentMonthSpent: 0
    };
  }

  trackUsage(cost) {
    this.budget.currentDaySpent += cost;
    this.budget.currentMonthSpent += cost;

    return {
      withinLimit: this.budget.currentDaySpent <= this.budget.dailyLimit,
      dayRemaining: this.budget.dailyLimit - this.budget.currentDaySpent,
      monthRemaining: this.budget.monthlyLimit - this.budget.currentMonthSpent
    };
  }

  resetDaily() {
    this.budget.currentDaySpent = 0;
  }

  save() {
    fs.writeFileSync(this.configPath, JSON.stringify(this.budget, null, 2));
  }
}

module.exports = { BudgetTracker };
```

