// Draft Validator
'use strict';

const fs = require('fs');
const path = require('path');

function validateDraft(draft, repoRoot) {
  const errors = [];
  const warnings = [];

  // Check for required fields
  if (!draft.title) {
    errors.push('Draft missing required field: title');
  }

  if (!draft.description) {
    errors.push('Draft missing required field: description');
  }

  if (!draft.implementResponse) {
    errors.push('Draft missing required field: implementResponse');
  }

  // Check file paths exist
  if (draft.implementResponse) {
    const filePaths = extractFilePaths(draft.implementResponse);

    for (const filePath of filePaths) {
      const fullPath = path.join(repoRoot, filePath);
      if (!fs.existsSync(fullPath)) {
        warnings.push(`Referenced file does not exist: ${filePath}`);
      }
    }
  }

  return {
    valid: errors.length === 0,
    errors,
    warnings
  };
}

function extractFilePaths(text) {
  const filePathRegex = /\b([a-zA-Z0-9_./-]+\.(js|ts|json|md|txt))\b/g;
  const paths = [];
  let match;

  while ((match = filePathRegex.exec(text)) !== null) {
    paths.push(match[1]);
  }

  return paths;
}

module.exports = { validateDraft, extractFilePaths };
```

This file validates drafts by checking for required fields and verifying that referenced file paths exist in the repository.
